class RLS(Learner):
    def __init__(self):
        super().__init__('full')
        self.writer='rls'

    def observe(self,z,bank,actual_byte):
        scores=self.scores(z,bank)
        residual=-scores;residual[actual_byte]+=1.
        p=self.inverse[bank];pz=p@z;den=1.+float(z@pz)
        gain=pz/den
        self.weights[bank]+=np.outer(gain,residual)
        p-=np.outer(pz,pz)/den
        self.writes[bank]+=1
        if not np.isfinite(self.weights[bank]).all():raise FloatingPointError('RLS nonfinite')
        return loss(scores,actual_byte),int(np.argmax(scores)==actual_byte),{'gain_norm':float(np.linalg.norm(gain)),'zpz':den-1,'cap':0.}


class ByteModel:
    """Live interface: raw past bytes and the subsequently observed byte only."""
    def __init__(self,seed,arm):
        self.arm=arm;self.stage='I' if arm in ARMS['I'] else 'II'
        self.encoder=Encoder(seed,'lag' if self.stage=='I' else 'last_fd')
        self.address_encoder=Encoder(seed,'lag')
        self.base=Dictionary() if arm=='DICT' else RLS() if arm=='H-RLS' else Learner('ordinary' if arm=='H-O' else 'full')
        self.eligible=set();self.shared=np.zeros((D,OUTPUTS)) if arm=='SHARED-R' else None
        # Immutable byte values prevent aliases/views from mutating another item's state.
        self.local={};self.aux_updates=0;self.locality_checks=0;self.ops=0

    def base_scores(self,h):
        z,b=self.encoder.encode(h)
        return self.base.scores(z,b)

    def scores(self,h):
        c=bytes(h)[-12:];s=self.base_scores(c)
        if self.stage=='I' or c not in self.eligible:return s
        if self.arm=='SHARED-R':return s+self.address_encoder.encode(c)[0]@self.shared
        if self.arm=='LOCAL-R':return s+np.frombuffer(self.local[c],dtype=np.float64)
        if self.arm=='LOCAL-V':return np.frombuffer(self.local[c],dtype=np.float64)
        return s

    def probabilities(self,h):
        return self.base.predict(h) if self.arm=='DICT' else softmax(self.scores(h))

    def observe(self,h,y):
        c=bytes(h)[-12:]
        if self.stage=='I':
            if self.arm=='DICT':return self.base.observe(c,y)
            z,b=self.encoder.encode(c);self.ops+=D*OUTPUTS+(D*D if self.base.inverse is not None else 0)
            return self.base.observe(z,b,y)
        z,b=self.encoder.encode(c);sb=self.base.scores(z,b);used=self.scores(c).copy()
        existed=c in self.eligible
        pre_loss=loss(used,y);correct=int(np.argmax(used)==y)
        base_loss=loss(sb,y);base_correct=int(np.argmax(sb)==y)
        self.base.observe(z,b,y)  # No auxiliary score is passed to the base.
        if not base_correct:self.eligible.add(c)
        touched=0;change=0.;local_norm=0.
        if c in self.eligible:
            residual=-used;residual[y]+=1.
            if self.arm=='SHARED-R':
                k,_=self.address_encoder.encode(c);kk=float(k@k)
                if kk>1e-15:
                    delta=RATE*np.outer(k/kk,residual);self.shared+=delta
                    change=float(np.linalg.norm(delta));self.aux_updates+=1
            elif self.arm in ('LOCAL-R','LOCAL-V'):
                before=self.local.copy()
                old=np.frombuffer(self.local[c],dtype=np.float64) if c in self.local else np.zeros(OUTPUTS)
                value=old+RATE*residual if self.arm=='LOCAL-R' else (1-RATE)*old
                if self.arm=='LOCAL-V':value[y]+=RATE
                value=np.asarray(value,dtype=np.float64)
                if not np.isfinite(value).all():raise FloatingPointError('Auxiliary state nonfinite')
                self.local[c]=value.tobytes()
                if len(self.local)!=len(before)+int(c not in before) or any(k!=c and self.local.get(k) is not v for k,v in before.items()):
                    raise AssertionError('Unrelated local vector changed')
                self.locality_checks+=1;self.aux_updates+=1;touched=1
                change=float(np.linalg.norm(value-old));local_norm=float(np.linalg.norm(value))
        self.ops+=D*OUTPUTS+D*D+(D*OUTPUTS if self.shared is not None else OUTPUTS*touched)
        return pre_loss,correct,{'base_bpb':base_loss,'base_accuracy':float(base_correct),
            'eligible_before':float(existed),'eligible_after':float(c in self.eligible),
            'newly_eligible':float(not existed and c in self.eligible),'local_vectors_touched':float(touched),
            'aux_change_norm':change,'aux_value_norm':local_norm}

    def eligibility_hash(self):return sha([c.hex() for c in sorted(self.eligible)])

    def state_hash(self):
        return sha(self.base.state_hash().encode()+self.eligibility_hash().encode()+
            (b'' if self.shared is None else self.shared.tobytes())+
            b''.join(len(c).to_bytes(1,'little')+c+v for c,v in sorted(self.local.items())))

    def costs(self):
        fixed=sum(a.nbytes for enc in (self.encoder,self.address_encoder) for a in
                  [enc.embedding,enc.centres,enc.bit_code,*enc.fast.values(),*enc.slow.values()])
        keys=sum(len(c) for c in self.eligible);vals=sum(len(v) for v in self.local.values())
        auxiliary=0 if self.shared is None else self.shared.nbytes
        base=self.base.costs(self.encoder)
        npbytes=auxiliary+fixed+(0 if self.arm=='DICT' else self.base.weights.nbytes+
                     (0 if self.base.inverse is None else self.base.inverse.nbytes)+self.base.writes.nbytes)
        overhead=sys.getsizeof(self.eligible)+sys.getsizeof(self.local)+sum(sys.getsizeof(c)-len(c) for c in self.eligible)+sum(sys.getsizeof(v)-len(v) for v in self.local.values())
        return {'base':base,'fixed_encoder_resident_bytes':fixed,'shared_residual_bytes':auxiliary,
            'eligible_contexts':len(self.eligible),'local_vectors':len(self.local),'exact_key_payload_bytes':keys,
            'local_vector_payload_bytes':vals,'resident_numpy_bytes':npbytes,
            'python_aux_overhead_estimate':overhead,'total_state_bytes_estimate':npbytes+keys+vals+overhead+
                (base.get('python_state_bytes_estimate',0) if self.arm=='DICT' else 0),
            'operation_proxy_multiply_add_units':self.ops,'locality_checks':self.locality_checks,
            'fixed_capacity':self.stage=='I' and self.arm!='DICT',
            'locality_check_peak_temporary_pointer_bytes_estimate':sys.getsizeof(self.local),
            'cost_notes':'Resident helper encoder tables counted, including unused reference tables. Python overhead approximate; evaluator sufficient statistics excluded.'}


def evaluate(model,stream,ids,expected=None,old=None):
    out={}
    for alias in range(3):
        rows=[]
        for i in list(ids):
            h=context(stream['keys'][i],alias);y=int(stream['labels'][i]) if expected is None else int(expected[i])
            p=model.probabilities(h)
            l=-math.log2(max(float(p[y]),1e-300)) if model.arm=='DICT' else loss(model.scores(h),y)
            bank=model.encoder.encode(h)[1]
            trained={model.encoder.encode(context(stream['keys'][i],a))[1] for a in (0,1)}
            rows.append({'accuracy':float(np.argmax(p)==y),'bpb':l,'target_probability':float(p[y]),
                         'obsolete_probability':None if old is None else float(p[int(old[i])]),
                         'route_match':bank in trained})
        def summary(rs):
            return {'n':len(rs),**{k:mean(r[k] for r in rs if r[k] is not None) for k in
                   ('accuracy','bpb','target_probability','obsolete_probability')}}
        out[str(alias)]=summary(rows)
        if alias:
            out[str(alias)]['route_conditioned']={str(match):summary([r for r in rows if r['route_match']==match]) for match in (True,False)}
            out[str(alias)]['route_match_fraction']=mean(float(r['route_match']) for r in rows)
            out[str(alias)]['route_note']='Fixed base-router diagnostic; local exact addressing and shared auxiliary matrix do not use this router.' if model.stage=='II' else 'Match to either acquired rendering bank; does not condition the strict primary endpoint.'
    return out


class OracleLedger:
    """Evaluator-only sufficient statistics; never fed to a live model."""
    def __init__(self):
        self.c=np.repeat(np.eye(D)[None],BANKS,axis=0);self.xy=np.zeros((BANKS,D,OUTPUTS))
        self.ct=self.c.copy();self.xyt=self.xy.copy()
    def observe(self,z,b,y,target):
        zz=np.outer(z,z);self.c[b]+=zz;self.xy[b,:,y]+=z
        if target:self.ct[b]+=zz;self.xyt[b,:,y]+=z
    def checkpoint(self,model,stream,wave,revised):
        solve=lambda c,xy:np.stack([np.linalg.solve(c[b],xy[b]) for b in range(BANKS)])
        w0=solve(self.c,self.xy);w1=solve(self.ct,self.xyt)
        err=float(np.max(np.abs(w0-model.base.weights)))
        pinv=np.stack([np.linalg.solve(c,np.eye(D)) for c in self.c])
        perr=float(np.max(np.abs(pinv-model.base.inverse)))
        if err>RLS_TOL or perr>RLS_TOL:raise AssertionError('O0 disagrees with online RLS')
        n=(ord(wave)-64)*stream['keys_per_wave'];xs=[[] for _ in range(BANKS)];ys=[[] for _ in range(BANKS)]
        current={i:int(stream['revisions'][i]) if revised and i in stream['revisions'] else int(stream['labels'][i]) for i in range(n)}
        for i in range(n):
            for a in (0,1):
                z,b=model.encoder.encode(context(stream['keys'][i],a));xs[b].append(z);ys[b].append(current[i])
        w2=np.zeros_like(w0);w3=np.zeros_like(w0);fits=[]
        for b in range(BANKS):
            if not xs[b]:continue
            x=np.array(xs[b]);y=np.eye(OUTPUTS)[ys[b]]
            w2[b]=np.linalg.solve(x.T@x+np.eye(D),x.T@y)
            w3[b]=np.linalg.pinv(x,rcond=PINV_RCOND)@y
            fits.append({'bank':b,'contexts':len(x),'rank':int(np.linalg.matrix_rank(x,tol=PINV_RCOND*np.linalg.svd(x,compute_uv=False)[0])),
                         'O3_max_score_residual':float(np.max(np.abs(x@w3[b]-y)))})
        outputs={}
        for name,w in [('O0',w0),('O1',w1),('O2',w2),('O3',w3)]:
            proxy=ByteModel(stream['seed'],'H-RLS');proxy.base.weights=w
            outputs[name]={'current_facts':evaluate(proxy,stream,range(n),current),
                'untouched_A':evaluate(proxy,stream,stream['untouched']),
                'revised_A':evaluate(proxy,stream,stream['revised'],current,stream['labels'])}
        return {'noncausal_evaluator_only':True,'O0_weight_max_error':err,'O0_inverse_max_error':perr,
            'O0_symmetry_max_error':float(np.max(np.abs(model.base.inverse-model.base.inverse.transpose(0,2,1)))),
            'O0_min_eigen_P':float(min(np.linalg.eigvalsh(p).min() for p in model.base.inverse)),
            'pinv_rcond':PINV_RCOND,'fits':fits,'oracles':outputs,
            'interpretation_limit':'Poor least-squares classification is not an impossibility proof for every possible linear classifier.'}


def eligibility_snapshot(model,stream,seen,seen_targets,wave):
    n=(ord(wave)-64)*stream['keys_per_wave']
    target={context(stream['keys'][i],a) for i in range(n) for a in (0,1)}
    untouched={context(stream['keys'][i],a) for i in stream['untouched'] for a in (0,1)}
    ratio=lambda keys:len(keys & model.eligible)/len(keys) if keys else None
    return {'total_eligible':len(model.eligible),'trained_target_coverage':ratio(target),
        'untouched_A_coverage':ratio(untouched),'seen_context_coverage':ratio(seen),
        'eligible_seen_target_count':len(model.eligible&seen_targets),
        'eligible_other_count':len(model.eligible-seen_targets),
        'base_hash':model.base.state_hash(),'eligibility_hash':model.eligibility_hash()}


def old_state(model,stream):
    out={}
    for i in stream['untouched']:
        for a in (0,1):
            c=context(stream['keys'][i],a)
            out[c]=(model.base_scores(c).copy(),model.scores(c).copy(),model.local.get(c))
    return out


def drift_summary(model,old):
    base=[];final=[];res=[];unchanged=[]
    for c,(b,s,v) in old.items():
        base.append(float(np.mean((model.base_scores(c)-b)**2)))
        final.append(float(np.mean((model.scores(c)-s)**2)))
        if v is not None:
            now=model.local.get(c);unchanged.append(now==v)
            res.append(float(np.mean((np.frombuffer(now,dtype=np.float64)-np.frombuffer(v,dtype=np.float64))**2)))
    return {'base_score_rms_drift':math.sqrt(mean(base)),'final_score_rms_drift':math.sqrt(mean(final)),
        'local_vector_rms_drift':None if not res else math.sqrt(mean(res)),
        'all_acquired_untouched_vectors_bit_identical':all(unchanged),'acquired_local_vectors':len(unchanged)}


def exposure_accounting(stream):
    raw=stream['raw'];rows=stream['rows']
    windows={raw[max(0,p-12):p] for p in range(len(raw))}
    return {'unique_logical_keys':len(stream['keys']),'trained_target_renderings':len({r['raw'][:12] for r in rows}),
        'heldout_target_renderings':len(stream['keys']),'distinct_raw_12byte_contexts':sum(len(c)==12 for c in windows),
        'distinct_contexts_including_startup':len(windows),
        'context_target_pairs':len({(raw[max(0,p-12):p],raw[p]) for p in range(len(raw))}),
        'target_context_target_pairs':len({r['raw'][:13] for r in rows}),
        'target_events':len(rows),'byte_events':len(raw),'initial_presentations_per_mapping':stream['repeats'],
        'per_key':[{'key_id':i,'acquisition':sum(r['key_id']==i and r['kind']=='acquisition' for r in rows),
        'noise':sum(r['key_id']==i and r['kind']=='one_off_noise' for r in rows),
        'revision':sum(r['key_id']==i and r['kind']=='revision' for r in rows),
        'rendering_presentations':[sum(r['key_id']==i and r['alias']==a for r in rows) for a in (0,1)]} for i in range(len(stream['keys']))]}


def run_trial(seed,arm,smoke=False,diagnostics=True):
    started=time.perf_counter();stream=make_stream(seed,False,smoke);model=ByteModel(seed,arm)
    history=bytearray();overall=Aggregate();target=Aggregate();non=Aggregate()
    groups=collections.defaultdict(Aggregate);cps=collections.defaultdict(list)
    for cp in stream['checkpoints']:cps[cp['record_count']].append(cp)
    snapshots={};noise=[];oracles={};eligibility={};old=None;drift={};geometry={}
    oracle=OracleLedger() if diagnostics and arm=='H-RLS' else None
    seen=set();seen_targets=set();pending=set();counts=collections.Counter();errors=collections.Counter()
    eligible_at_occurrence=collections.defaultdict(list);activation_errors=[]
    readonly=0;k=stream['keys_per_wave']
    for number,row in enumerate(stream['rows'],1):
        if diagnostics and row['kind']=='one_off_noise':
            nb=evaluate(model,stream,[row['key_id']]);ob=evaluate(model,stream,stream['untouched'])
        for pos,y in enumerate(row['raw']):
            c=bytes(history);was=c in model.eligible
            if diagnostics:
                seen.add(c);counts[c]+=1
                if pos==12:seen_targets.add(c)
            if oracle is not None:
                z,b=model.encoder.encode(c);oracle.observe(z,b,y,pos==12)
            if diagnostics and pos==12 and row['kind']=='one_off_noise':
                immediate_before=evaluate(model,stream,[row['key_id']],old=stream['labels'])
                before_local=model.local.get(c);before_eligible=was
            l,a,d=model.observe(history,y)
            overall.add(l,a,d);groups['all_'+row['wave']].add(l,a,d)
            if pos==12:
                target.add(l,a,d);groups['target_'+row['wave']].add(l,a,d)
                groups[f"{row['kind']}_{row['wave']}_{row['exposure']}"].add(l,a,d)
                groups[f"render_{row['kind']}_{row['wave']}_{row['rendering_exposure']}"].add(l,a,d)
            else:non.add(l,a,d)
            if diagnostics and model.stage=='II':
                errors[c]+=int(not d['base_accuracy'])
                if c in pending:
                    if pos==12:groups['first_exact_recurrence_after_creation'].add(l,a,d)
                    pending.remove(c)
                if not was and c in model.eligible:
                    pending.add(c);activation_errors.append(errors[c])
                if pos==12 and row['kind']=='acquisition':
                    eligible_at_occurrence[str(row['rendering_exposure'])].append(float(c in model.eligible))
            if diagnostics and pos==12 and row['kind']=='one_off_noise':
                immediate_after=evaluate(model,stream,[row['key_id']],old=stream['labels'])
                changed_local=model.local.get(c)
                local_delta=None if before_local is None or changed_local is None else float(np.linalg.norm(np.frombuffer(changed_local,dtype=np.float64)-np.frombuffer(before_local,dtype=np.float64)))
                wrong_after=float(model.probabilities(c)[y])
            history.append(y)
            if len(history)>12:del history[0]
        if diagnostics and row['kind']=='one_off_noise':
            noise.append({'key_id':row['key_id'],'before':nb,'after':evaluate(model,stream,[row['key_id']]),
                'others_before':ob,'others_after':evaluate(model,stream,stream['untouched']),
                'target_immediate_before':immediate_before,'target_immediate_after':immediate_after,
                'wrong_target_probability_immediately_after':wrong_after,'eligible_before':before_eligible,
                'local_vector_change_norm':local_delta})
        if not diagnostics:continue
        for cp in cps.get(number,[]):
            state=model.state_hash();s=dict(cp,bytes_observed=number*14);wi=ord(cp['wave'])-65
            if cp['type']=='acquisition':s['current']=evaluate(model,stream,range(wi*k,(wi+1)*k))
            else:
                revised=cp['type']=='revision' or cp['wave']=='D'
                s['untouched_A']=evaluate(model,stream,stream['untouched'])
                s['noise_A']=evaluate(model,stream,stream['noisy'])
                s['revised_A']=evaluate(model,stream,stream['revised'],stream['revisions'] if revised else None,stream['labels'] if revised else None)
                s['cohorts']={chr(65+w):evaluate(model,stream,range(w*k,(w+1)*k)) for w in range(1,wi+1)}
                if oracle is not None:oracles[cp['name']]=oracle.checkpoint(model,stream,cp['wave'],revised)
                if cp['type']=='wave' and arm!='DICT':geometry[cp['wave']]=model.base.geometry()
            if model.stage=='II':
                eligibility[cp['name']]=eligibility_snapshot(model,stream,seen,seen_targets,cp['wave'])
                if cp['name']=='after_A':old=old_state(model,stream)
                if cp['type']=='wave' and old is not None:drift[cp['wave']]=drift_summary(model,old)
            if state!=model.state_hash():raise AssertionError('Observer changed learned state')
            readonly+=1;snapshots[cp['name']]=s
    r={'seed':seed,'arm':arm,'stage':model.stage,'smoke':smoke,'diagnostics':diagnostics,
        'stream_sha256':stream['raw_sha256'],'state_sha256':model.state_hash(),
        'base_state_sha256':model.base.state_hash(),'eligibility_sha256':model.eligibility_hash(),
        'whole_stream':overall.result(),'target_stream':target.result(),'nontarget_stream':non.result(),
        'groups':{name:g.result() for name,g in groups.items()},'snapshots':snapshots,'oracles':oracles,
        'noise_events':noise,'covariance_geometry':geometry,'eligibility':eligibility,'base_drift':drift,
        'target_eligibility_by_exact_occurrence':{e:mean(v) for e,v in eligible_at_occurrence.items()},
        'base_errors_at_activation':{'n':len(activation_errors),'mean':mean(activation_errors),'max':max(activation_errors,default=0)},
        'costs':model.costs(),'counts':exposure_accounting(stream),'readonly_checks':readonly,
        'elapsed_seconds':time.perf_counter()-started}
    r['metrics']=metrics(r) if diagnostics else {}
    return r


def metrics(r):
    m={'whole_bpb':r['whole_stream']['bpb'],'target_bpb':r['target_stream']['bpb'],'nontarget_bpb':r['nontarget_stream']['bpb']}
    s=r['snapshots'];g=r['groups']
    m['A_initial_accuracy']=view_average(s['after_A']['untouched_A'])
    initial_loss=view_average(s['after_A']['untouched_A'],'bpb');m['A_initial_bpb']=initial_loss
    for w in 'ABCD':
        pr=s['after_'+w]['untouched_A'];m['A_after_'+w]=view_average(pr);m['A_bpb_after_'+w]=view_average(pr,'bpb')
        m['A_heldout_after_'+w]=pr['2']['accuracy']
        for chance,denom in [(1/256,'256'),(1/24,'24')]:
            m['retention_fraction_'+w+'_'+denom]=(m['A_after_'+w]-chance)/(m['A_initial_accuracy']-chance) if m['A_initial_accuracy']>=.9 else None
        m['loss_retention_fraction_'+w]=(8-m['A_bpb_after_'+w])/(8-initial_loss) if m['A_initial_accuracy']>=.9 and 8-initial_loss>.5 else None
        for ex in (1,2,4,8,16,32):m[f'{w}_acquisition_{ex}']=g.get(f'acquisition_{w}_{ex}',{}).get('accuracy')
        m[w+'_first_exact_repeat']=g['render_acquisition_'+w+'_2']['accuracy']
        if w!='A':m[w+'_current']=view_average(s['after_'+w]['cohorts'][w])
    m['new_second_prequential']=mean(m[w+'_acquisition_2'] for w in 'BCD')
    for ex in (1,2,4,8):
        for a in ('0','1','2'):
            pr=s[f'revision_{ex}']['revised_A'][a]
            m[f'revision_{ex}_alias_{a}']=pr['accuracy'];m[f'obsolete_{ex}_alias_{a}']=pr['obsolete_probability']
        m[f'revision_{ex}_prequential']=g[f'revision_C_{ex}']['accuracy']
    m['noise_damage']=mean(view_average(n['before'])-view_average(n['after']) for n in r['noise_events'])
    m['noise_unrelated_damage']=mean(view_average(n['others_before'])-view_average(n['others_after']) for n in r['noise_events'])
    if r['stage']=='II':
        m['eligibility_A']=r['eligibility']['after_A']['untouched_A_coverage']
        m['first_exact_recurrence_after_creation']=g.get('first_exact_recurrence_after_creation',{}).get('accuracy')
        m['base_whole_bpb']=r['whole_stream']['base_bpb']
    return m


def level(records,arm,key,seeds):
    ix={(r['seed'],r['arm']):r for r in records}
    return stat([ix.get((seed,arm),{}).get('metrics',{}).get(key) for seed in seeds])


def difference(records,a,b,key,seeds):
    va=level(records,a,key,seeds)['values'];vb=level(records,b,key,seeds)['values']
    return stat([None if x is None or y is None else x-y for x,y in zip(va,vb)])


def acquisition(records,arm,seeds):
    a=level(records,arm,'A_initial_accuracy',seeds);d=level(records,arm,'D_current',seeds)
    complete=a['n']==len(seeds) and d['n']==len(seeds)
    return {'passed':bool(complete and a['mean']>=.9 and min(a['values'])>=.75 and d['mean']>=.9),
            'A_after_A':a,'D_current':d,'minimum_seed_A':min(a['values']) if complete else None}


def graded(effect,valid=True,qualified=False,coverage=True):
    if not coverage and not qualified:return 'ownership_unresolved_due_to_eligibility'
    if not valid:return 'invalid_acquisition'
    if qualified:return 'qualified'
    if effect['high'] is not None and effect['high']<0:return 'adverse'
    if effect['low'] is not None and effect['low']>0:return 'supported_below_qualification'
    if effect['mean'] is not None and effect['mean']>0:return 'favorable_unresolved_precision'
    return 'no_mean_advantage'


def stage1_report(records,seeds):
    qual={a:acquisition(records,a,seeds) for a in ARMS['I'] if a!='DICT'}
    eff=difference(records,'H-RLS','H-P','A_after_D',seeds)
    lev=lambda k:level(records,'H-RLS',k,seeds)
    delta=lambda k:difference(records,'H-RLS','H-P',k,seeds)
    ge=lambda s,t:s['n']==len(seeds) and s['mean'] is not None and s['mean']>=t
    le=lambda s,t:s['n']==len(seeds) and s['mean'] is not None and s['mean']<=t
    gates={'S1':qual['H-RLS']['passed'],'S2':ge(lev('A_after_D'),.75),
        'S3':ge(eff,.2) and eff['low'] is not None and eff['low']>0,
        'S4':delta('D_current')['low'] is not None and delta('D_current')['low']>=-.05,
        'S5':ge(delta('new_second_prequential'),-.15),
        'S6':ge(lev('revision_4_alias_0'),.9) and le(lev('obsolete_8_alias_0'),.1)}
    passed=all(gates.values());c0=difference(records,'H-P','H-O','A_after_D',seeds)
    def effect_record(a,b,e,valid,qualified=False):
        return {'candidate':a,'comparator':b,'retention_difference':e,
            'D_difference':difference(records,a,b,'D_current',seeds),
            'target_bpb_difference':difference(records,a,b,'target_bpb',seeds),
            'statistical_effect':graded(e,valid),
            'architectural_qualification':graded(e,valid,qualified)}
    c0valid=qual['H-O']['passed'] and qual['H-P']['passed']
    c0report=effect_record('H-P','H-O',c0,c0valid);c0report['architectural_qualification']='not_tested_by_C0'
    complete=all(level(records,a,'A_after_D',seeds)['n']==len(seeds) for a in ARMS['I'])
    bpb=delta('whole_bpb')
    return {'complete':complete,'qualified':passed,'gates':gates,'acquisition':qual,
        'primary':effect_record('H-RLS','H-P',eff,qual['H-RLS']['passed'] and qual['H-P']['passed'],passed),
        'C0':c0report,'early_learning_difference':delta('new_second_prequential'),
        'revision_4_exact':lev('revision_4_alias_0'),'obsolete_8_exact':lev('obsolete_8_alias_0'),
        'whole_bpb_difference':bpb,'nontarget_bpb_difference':delta('nontarget_bpb'),
        'shared_storage_status':('shared_storage_qualified__calibration_unresolved' if bpb['mean']>0 else 'qualified') if passed else 'not_qualified',
        'run_stage_II':complete and not passed}


def stage2_report(records,seeds):
    aq={a:acquisition(records,a,seeds) for a in ARMS['II']}
    lev=lambda k:level(records,'LOCAL-V',k,seeds)
    diff=lambda a,b,k:difference(records,a,b,k,seeds)
    full=lambda s:s['n']==len(seeds) and s['mean'] is not None
    ge=lambda s,t:full(s) and s['mean']>=t
    le=lambda s,t:full(s) and s['mean']<=t
    gain=diff('LOCAL-V','SHARED-R','A_after_D');bp=diff('LOCAL-V','BASE','whole_bpb')
    gates={'L1':ge(lev('eligibility_A'),.9),'L2':aq['LOCAL-V']['passed'],
        'L3':ge(lev('A_after_D'),.9),
        'L4':ge(gain,.2) and gain['low'] is not None and gain['low']>0,
        'L5':ge(lev('revision_2_prequential'),.75) and ge(lev('revision_4_alias_0'),.9) and le(lev('obsolete_8_alias_0'),.1),
        'L6':le(bp,.1)}
    passed=all(gates.values());effects={}
    for name,a,b in [('R1','SHARED-R','BASE'),('R2','LOCAL-R','SHARED-R'),('R3','LOCAL-V','LOCAL-R'),('L4','LOCAL-V','SHARED-R')]:
        ef=diff(a,b,'A_after_D');valid=aq[a]['passed']
        coverage=gates['L1'] if a.startswith('LOCAL') else True
        effects[name]={'candidate':a,'comparator':b,'retention_difference':ef,
            'statistical_effect':graded(ef,valid,coverage=coverage),
            'architectural_qualification':graded(ef,valid,passed if a=='LOCAL-V' else False,coverage),
            'D_difference':diff(a,b,'D_current'),'whole_bpb_difference':diff(a,b,'whole_bpb')}
    return {'complete':all(level(records,a,'A_after_D',seeds)['n']==len(seeds) for a in ARMS['II']),
        'qualified':passed,'gates':gates,'acquisition':aq,'contrasts':effects,
        'eligibility_coverage':lev('eligibility_A'),'whole_bpb_difference':bp,
        'historical_75pct_retention':ge(lev('A_after_D'),.75),
        'ownership_status':graded(gain,aq['LOCAL-V']['passed'],passed,gates['L1']),
        'scope':'Unbounded exact-context ownership only. No bounded lifelong claim.'}


def build_report(records,smoke=False):
    seeds=ENGINEERING if smoke else SEEDS
    one=stage1_report(records,seeds['I']);two=stage2_report(records,seeds['II']) if one['run_stage_II'] else None
    complete=one['complete'] and (not one['run_stage_II'] or two['complete'])
    levels={a:{k:level(records,a,k,seeds[st]) for k in sorted({k for r in records if r['arm']==a for k in r['metrics']})} for st in ARMS for a in ARMS[st]}
    checks=[]
    for seed in seeds['II']:
        rr=[r for r in records if r['seed']==seed]
        if len(rr)==4:
            base=len({r['base_state_sha256'] for r in rr})==1;elig=len({r['eligibility_sha256'] for r in rr})==1
            cps=all(len({r['eligibility'][c]['base_hash'] for r in rr})==1 and len({r['eligibility'][c]['eligibility_hash'] for r in rr})==1 for c in rr[0]['eligibility'])
            if not (base and elig and cps):raise AssertionError('Stage-II base/eligibility mismatch')
            checks.append({'seed':seed,'base_identical':base,'eligibility_identical':elig,'all_checkpoints_identical':cps})
    return {'version':VERSION,'status':'complete' if complete else 'partial','scientific':not smoke,
        'completed_trajectories':len(records),'expected_trajectories':len(seeds['I'])*4+(len(seeds['II'])*4 if one['run_stage_II'] else 0),
        'stage_I':one,'stage_II':two,'levels':levels,'stage_II_causal_invariants':checks,
        'historical_C0':[{'round':'V33','H-O':.0546875,'H-P':.21875,'difference':.1640625},
                         {'round':'V34','H-O':.0703125,'H-P':.15625,'difference':.0859375}],
        'units':'Independent seeds; accuracy differences in fraction units; two-sided paired 95% Student-t CIs.',
        'no_automatic_stage_III':True}


def csv_output(path,rows):
    keys=list(dict.fromkeys(k for r in rows for k in r))
    out=io.StringIO();writer=csv.DictWriter(out,fieldnames=keys);writer.writeheader()
    for r in rows:writer.writerow({k:encode_json(v) if isinstance(v,(dict,list)) else v for k,v in r.items()})
    atomic(path,out.getvalue())


def summary_text(report):
    lines=['# V35 — Shared Solver and Local Ownership Isolate','',
        f"Status: {report['status']}; {report['completed_trajectories']} trajectories. "+('Scientific run.' if report['scientific'] else 'Engineering smoke only; not scientific evidence.'),'',
        '| Arm | n | A after A | A after D | D current | Whole bpb | Target bpb |',
        '|---|---:|---:|---:|---:|---:|---:|']
    def fmt(x,pct=False):return 'n/a' if x is None else f'{x:.2%}' if pct else f'{x:.4f}'
    for arm,ls in report['levels'].items():
        if not ls:continue
        vals=[fmt(ls[k]['mean'],k in ('A_initial_accuracy','A_after_D','D_current')) for k in
              ('A_initial_accuracy','A_after_D','D_current','whole_bpb','target_bpb')]
        lines.append('| '+arm+' | '+str(ls['A_after_D']['n'])+' | '+' | '.join(vals)+' |')
    lines+=['','Stage I: '+report['stage_I']['shared_storage_status'],
        'S1–S6: '+encode_json(report['stage_I']['gates']),'',
        '| Contrast | Mean A-after-D difference | Paired 95% CI | Statistical effect | Architectural qualification |',
        '|---|---:|---|---|---|']
    contrasts={'C0':report['stage_I']['C0'],'RLS−H-P':report['stage_I']['primary']}
    if report['stage_II']:
        contrasts.update(report['stage_II']['contrasts'])
    for name,c in contrasts.items():
        e=c['retention_difference']
        lines.append(f"| {name} | {fmt(e['mean'],True)} | [{fmt(e['low'],True)}, {fmt(e['high'],True)}] | {c['statistical_effect']} | {c['architectural_qualification']} |")
    if report['stage_II']:
        lines+=['','Stage II: '+report['stage_II']['ownership_status'],'L1–L6: '+encode_json(report['stage_II']['gates'])]
    else:lines+=['','Stage II: '+('skipped because all S1–S6 passed.' if report['stage_I']['qualified'] else 'awaiting complete Stage I.')]
    lines+=['','Raw per-seed endpoints are in SUMMARY.csv. Noncausal O0–O3 fits are in ORACLES.json; they are never live learners.',
        'A positive interval can support an effect below architectural thresholds. A nonsignificant interval is not equivalence.',
        'Stage II is unbounded exact-context storage. V35 cannot qualify a bounded lifelong architecture.','']
    return '\n'.join(lines)


def make_plan(smoke=False):
    seeds=ENGINEERING if smoke else SEEDS
    jobs=[{'stage':st,'seed':seed,'arm':arm,'smoke':smoke} for st in ARMS for seed in seeds[st] for arm in ARMS[st]]
    return {'version':VERSION,'jobs':jobs,'streams':{str(s):make_stream(s,False,smoke)['raw_sha256'] for ss in seeds.values() for s in ss},
        'protocol_sha256':sha(PROTOCOL.encode()),'completion_notes_sha256':sha(COMPLETION_NOTES.encode()),
        'stage_II_trigger':'Only after all Stage I jobs and at least one S1-S6 failure.',
        'scientific_max_jobs':64,'no_stage_III':True,'seed_audit_sha256':sha(SEED_AUDIT)}


class Runner:
    def __init__(self,root,smoke=False,max_new=None):
        self.root=root;self.smoke=smoke;self.max_new=max_new;self.new=0;self.reused=0;self.records=[]
        self.source=Path(__file__).read_bytes();self.plan=make_plan(smoke)
        self.identity={'source_sha256':sha(self.source),'protocol_sha256':sha(PROTOCOL.encode()),'plan_sha256':sha(self.plan)}
    def setup(self):
        path=self.root/'RUN_MANIFEST.json'
        if path.exists():
            manifest=json.loads(path.read_text())
            if any(manifest.get(k)!=v for k,v in self.identity.items()):raise RuntimeError('Resume rejected: source/protocol/plan changed')
            env={'python':sys.version,'numpy':np.__version__,'scipy':importlib.import_module('scipy').__version__,'platform':platform.platform()}
            if manifest.get('environment')!=env:raise RuntimeError('Resume rejected: numerical environment changed; use a new directory')
            if json.loads((self.root/'PLAN.json').read_text())!=self.plan:raise RuntimeError('Corrupt plan')
        else:
            if any(self.root.glob('jobs/*.json')):raise RuntimeError('Orphan jobs without manifest')
            manifest=dict(self.identity,version=VERSION,environment={'python':sys.version,'numpy':np.__version__,
                'scipy':importlib.import_module('scipy').__version__,'platform':platform.platform()},blas_threads=1,
                references={k:v['sha256'] for k,v in REFERENCES.items()},seed_audit=SEED_AUDIT)
            write_json(path,manifest);write_json(self.root/'PLAN.json',self.plan)
        self.manifest=manifest
        atomic(self.root/'PROTOCOL.md',PROTOCOL);atomic(self.root/'IMPLEMENTATION_CHOICES.md',COMPLETION_NOTES)
        atomic(self.root/Path(__file__).name,self.source.decode());(self.root/'jobs').mkdir(exist_ok=True)
        allowed={sha(j):j for j in self.plan['jobs']}
        for p in (self.root/'jobs').glob('*.json'):
            if p.stem not in allowed:raise RuntimeError('Foreign job '+p.name)
            self.load_job(allowed[p.stem])
        # A Stage-II cache cannot override the locked conditional decision.
        cached=[self.load_job(j) for j in self.plan['jobs']]
        cached=[r for r in cached if r is not None]
        if any(r['stage']=='II' for r in cached):
            s=stage1_report(cached,(ENGINEERING if self.smoke else SEEDS)['I'])
            if not s['complete'] or not s['run_stage_II']:raise RuntimeError('Stage II records are ineligible under Stage I')
    def load_job(self,j):
        path=self.root/'jobs'/(sha(j)+'.json')
        if not path.exists():return None
        e=json.loads(path.read_text());p=e['payload']
        if e.get('sha256')!=sha(p) or p.get('identity')!=self.identity or p.get('descriptor')!=j:raise RuntimeError('Corrupt or mismatched job '+path.name)
        r=p['result']
        if any(r.get(k)!=v for k,v in j.items()) or r['stream_sha256']!=self.plan['streams'][str(j['seed'])]:raise RuntimeError('Wrong result identity')
        if r['metrics']!=metrics(r):raise RuntimeError('Cached metrics differ from result')
        if r['counts']['byte_events']!=r['whole_stream']['n']:raise RuntimeError('Event accounting mismatch')
        return r
    def run(self):
        for j in self.plan['jobs']:
            if j['stage']=='II':
                s=stage1_report(self.records,(ENGINEERING if self.smoke else SEEDS)['I'])
                if not s['complete']:raise AssertionError('Conditional stage before complete Stage I')
                if not s['run_stage_II']:return True
            r=self.load_job(j)
            if r is None:
                if self.max_new is not None and self.new>=self.max_new:return False
                print(f"Starting {j['stage']} {j['seed']} {j['arm']}",flush=True)
                r=run_trial(j['seed'],j['arm'],self.smoke)
                p={'descriptor':j,'identity':self.identity,'result':r}
                write_json(self.root/'jobs'/(sha(j)+'.json'),{'payload':p,'sha256':sha(p)});self.new+=1
                print(f"Completed {j['arm']}: {r['elapsed_seconds']:.1f}s",flush=True)
            else:self.reused+=1
            self.records.append(r)
            write_json(self.root/'STATUS.json',{'status':'running','completed':len(self.records),'new':self.new,'reused':self.reused})
        return True
    def finish(self,complete):
        report=build_report(self.records,self.smoke)
        if not complete:report['status']='paused'
        write_json(self.root/'REPORT.json',report);atomic(self.root/'SUMMARY.md',summary_text(report))
        csv_output(self.root/'SUMMARY.csv',[{'seed':r['seed'],'arm':r['arm'],**r['metrics']} for r in self.records])
        for filename,key in [('ORACLES','oracles'),('NOISE','noise_events'),('ELIGIBILITY','eligibility'),('BASE_DRIFT','base_drift'),('COSTS','costs'),('COVARIANCE','covariance_geometry'),('EXPOSURES','counts')]:
            write_json(self.root/(filename+'.json'),[{'seed':r['seed'],'arm':r['arm'],'data':r[key]} for r in self.records])
        rev=[];acq=[];ret=[]
        for r in self.records:
            ident={'seed':r['seed'],'arm':r['arm']}
            for cp in r['snapshots'].values():
                if cp['type']=='revision':
                    for a,p in cp['revised_A'].items():rev.append(dict(ident,exposure=cp['exposure'],alias=a,**p))
                if cp['type']=='acquisition':
                    for a,p in cp['current'].items():acq.append(dict(ident,wave=cp['wave'],exposure=cp['exposure'],alias=a,**p))
                if cp['type']=='wave':
                    for a,p in cp['untouched_A'].items():ret.append(dict(ident,wave=cp['wave'],alias=a,**p))
        csv_output(self.root/'REVISION_CURVES.csv',rev);csv_output(self.root/'ACQUISITION_CURVES.csv',acq);csv_output(self.root/'RETENTION_BY_WAVE.csv',ret)
        write_json(self.root/'C0_REPLICATION.json',{'historical':report['historical_C0'],'V35':report['stage_I']['C0']})
        write_json(self.root/'CAUSAL_INVARIANTS.json',report['stage_II_causal_invariants'])
        write_json(self.root/'STATUS.json',{'status':report['status'],'completed':len(self.records),'new':self.new,'reused':self.reused})
        paths=[p for p in self.root.rglob('*') if p.is_file() and not p.name.startswith('.') and '.tmp-' not in p.name and p.name!='ARTIFACT_HASHES.json']
        write_json(self.root/'ARTIFACT_HASHES.json',{str(p.relative_to(self.root)):sha(p.read_bytes()) for p in paths})
        temp=self.root.with_suffix('.zip.tmp');archive=self.root.with_suffix('.zip')
        with zipfile.ZipFile(temp,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
            for p in paths+[self.root/'ARTIFACT_HASHES.json']:z.write(p,p.relative_to(self.root))
        os.replace(temp,archive)
        print(f"{report['status']}: {self.new} new, {self.reused} reused; {archive}",flush=True)


def pinned_sources():
    sources={}
    for v,ref in REFERENCES.items():
        raw=zlib.decompress(base64.b85decode(ref['source_b85']))
        if sha(raw)!=ref['sha256']:raise AssertionError('Pinned archived source mismatch: '+v)
        sources[v]=raw.decode()
    # Verify copied reference definitions semantically against the pinned archive.
    own={n.name:ast.dump(n,include_attributes=False) for n in ast.parse(Path(__file__).read_text()).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    ref={n.name:ast.dump(n,include_attributes=False) for n in ast.parse(sources['v32']).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    for name in COPIED_DEFINITIONS:
        if own[name]!=ref[name]:raise AssertionError('Copied historical definition drift: '+name)
    ref33={n.name:ast.dump(n,include_attributes=False) for n in ast.parse(sources['v33']).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
    for name in ('Encoder','direction','make_stream','Dictionary','context'):
        if own[name]!=ref33[name]:raise AssertionError('V33 lineage changed: '+name)
    return sources


def self_tests():
    sources=pinned_sources();tests=[]
    def check(name,cond):
        if not cond:raise AssertionError(name)
        tests.append(name)
    rng=np.random.default_rng(975399)
    for name,z,y in [
        ('random',rng.normal(size=(50,12)),rng.integers(0,5,50)),
        ('identical',np.tile(rng.normal(size=12),(40,1)),np.zeros(40,dtype=int)),
        ('orthogonal',np.eye(12),np.arange(12)%5),
        ('collinear',np.ones((40,12))+1e-9*rng.normal(size=(40,12)),rng.integers(0,5,40)),
        ('contradictory',np.ones((40,12)),np.arange(40)%5)]:
        x=z/np.linalg.norm(z,axis=1,keepdims=True);Y=np.eye(5)[y];p=np.eye(12);w=np.zeros((12,5))
        for xi,yi in zip(x,Y):
            pz=p@xi;den=1+xi@pz;w+=np.outer(pz/den,yi-xi@w);p-=np.outer(pz,pz)/den
        wb=np.linalg.solve(x.T@x+np.eye(12),x.T@Y)
        check(name+'_ridge',np.max(np.abs(w-wb))<1e-11)
        check(name+'_inverse',np.max(np.abs(p-np.linalg.inv(x.T@x+np.eye(12))))<1e-11)
        check(name+'_symmetry_spd',np.max(np.abs(p-p.T))<1e-12 and np.linalg.eigvalsh(p).min()>0)
    m=RLS();x=rng.normal(size=(48,D));x/=np.linalg.norm(x,axis=1,keepdims=True);ys=rng.integers(0,OUTPUTS,48)
    for i,(z,y) in enumerate(zip(x,ys)):m.observe(z,i%3,int(y))
    for b in range(3):
        xx=x[b::3];yy=np.eye(OUTPUTS)[ys[b::3]]
        check('actual_RLS_bank_'+str(b),np.max(np.abs(m.weights[b]-np.linalg.solve(xx.T@xx+np.eye(D),xx.T@yy)))<1e-11)
    check('unselected_bank',not np.any(m.weights[3:]) and np.array_equal(m.inverse[3],np.eye(D)))
    # Byte-exact serialization/resume of learned state, then identical continuation.
    clone=copy.deepcopy(m)
    clone.weights=np.frombuffer(m.weights.tobytes(),dtype=np.float64).copy().reshape(m.weights.shape)
    clone.inverse=np.frombuffer(m.inverse.tobytes(),dtype=np.float64).copy().reshape(m.inverse.shape)
    for z,y in zip(x,ys):m.observe(z,0,int(y));clone.observe(z,0,int(y))
    check('RLS_pause_resume_bits',m.state_hash()==clone.state_hash())
    stream=make_stream(975399,False,True)
    for a in ARMS['II']:
        bm=ByteModel(975399,a);h=b'123456789abc';bm.observe(h,120)
        before=bm.state_hash();bm.probabilities(h);evaluate(bm,stream,[0])
        check(a+'_readonly',before==bm.state_hash())
        bm.observe(b'abcdefghijkl',121)
        if a.startswith('LOCAL'):check(a+'_ownership',bm.locality_checks==2)
    check('seed_blocks_disjoint',not set(SEEDS['I'])&set(SEEDS['II']) and not set(SEEDS['I']+SEEDS['II'])&set(ENGINEERING['I']+ENGINEERING['II']))
    check('source_seed_audit',not SEED_AUDIT['collisions'])
    check('zero_variance_CI',stat([1]*8)['low']==1)
    check('missing_CI',stat([1,None])['low'] is None)
    check('graded_supported',graded(stat([.1]*8))=='supported_below_qualification')
    check('graded_adverse',graded(stat([-.1]*8))=='adverse')
    check('graded_invalid',graded(stat([.1]*8),False)=='invalid_acquisition')
    # Synthetic reporting fixtures exercise the complete skip/run decision without scientific trials.
    fake=[]
    for seed in ENGINEERING['I']:
        for a in ARMS['I']:
            mm={'A_initial_accuracy':1.,'D_current':1.,'A_after_D':.9 if a=='H-RLS' else .5,
                'new_second_prequential':.8,'revision_4_alias_0':1.,'obsolete_8_alias_0':.01,
                'whole_bpb':2.,'target_bpb':2.,'nontarget_bpb':2.}
            fake.append({'seed':seed,'arm':a,'metrics':mm})
    report=stage1_report(fake,ENGINEERING['I']);check('all_gates_skip',report['qualified'] and not report['run_stage_II'])
    for key,value in [('A_initial_accuracy',.1),('A_after_D',.1),('D_current',.1),('new_second_prequential',.1),('revision_4_alias_0',.1),('obsolete_8_alias_0',.9)]:
        f=copy.deepcopy(fake)
        for r in f:
            if r['arm']=='H-RLS':r['metrics'][key]=value
        check('trigger_'+key,stage1_report(f,ENGINEERING['I'])['run_stage_II'])
    return {'passed':len(tests),'checks':tests,'pinned_source_hashes':{k:r['sha256'] for k,r in REFERENCES.items()}}


def reference_module(source,name):
    ns={'__name__':name,'__file__':str(Path(__file__).resolve())};exec(compile(source,name,'exec'),ns);ns['dependencies'](False);return ns


def engineering_verification(full=False):
    """No scientific seeds. Full verification includes every family with/without observers."""
    checks=self_tests();sources=pinned_sources();rows=[]
    seed=975399;smoke=not full
    ref=reference_module(sources['v32'],'v32_reference')
    # Replay independently through the archived reference to retain a final state hash.
    stream=ref['make_stream'](seed,False,smoke)
    expected={}
    for kind,writer,arm in [('last_fd','full','BASE'),('lag','ordinary','H-O'),('lag','full','H-P')]:
        enc=ref['Encoder'](seed,kind);model=ref['Learner'](writer);hist=bytearray();agg=ref['Aggregate']()
        for y in stream['raw']:
            z,b=enc.encode(hist);l,a,d=model.observe(z,b,int(y));agg.add(l,a,d)
            hist.append(y)
            if len(hist)>12:del hist[0]
        expected[arm]=(model.state_hash(),agg.result()['bpb'],ref['probe'](model,enc,stream,stream['untouched']))
    for arm in [*ARMS['I'],*ARMS['II']]:
        print('Engineering observer verification: '+arm,flush=True)
        yes=run_trial(seed,arm,smoke,True);no=run_trial(seed,arm,smoke,False)
        if yes['state_sha256']!=no['state_sha256'] or yes['whole_stream']!=no['whole_stream'] or yes['target_stream']!=no['target_stream']:
            raise AssertionError('Observer effect: '+arm)
        if arm in expected:
            if (yes['base_state_sha256'],yes['whole_stream']['bpb'])!=expected[arm][:2]:raise AssertionError('Historical reference mismatch '+arm)
            for alias,pr in expected[arm][2].items():
                if any(yes['snapshots']['after_D']['untouched_A'][alias][k]!=v for k,v in pr.items()):raise AssertionError('Historical terminal metric mismatch '+arm)
        rows.append({'arm':arm,'state_sha256':yes['state_sha256'],'base_sha256':yes['base_state_sha256'],
            'eligibility_sha256':yes['eligibility_sha256'],'observer_identical':True,
            'archived_v32_reference_identical':arm in expected,'whole_bpb':yes['whole_stream']['bpb'],
            'O0_max_error':max((v['O0_weight_max_error'] for v in yes['oracles'].values()),default=0)})
    ii=[r for r in rows if r['arm'] in ARMS['II']]
    if len({r['base_sha256'] for r in ii})!=1 or len({r['eligibility_sha256'] for r in ii})!=1:raise AssertionError('Cross-arm causal invariant')
    return {'startup':checks,'full_length':full,'seed':seed,'stream_sha256':stream['raw_sha256'],
        'trajectories':16,'independent_archived_replays':3,'observer_audit':rows,
        'source_sha256':sha(Path(__file__).read_bytes()),'scientific_outcomes_observed':False}


def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--install-deps',action='store_true');ap.add_argument('--smoke',action='store_true')
    ap.add_argument('--self-test',action='store_true');ap.add_argument('--verify',action='store_true')
    ap.add_argument('--output',type=Path);ap.add_argument('--max-new-jobs',type=int)
    args=ap.parse_args(argv);dependencies(args.install_deps)
    if args.max_new_jobs is not None and args.max_new_jobs<0:ap.error('--max-new-jobs must be nonnegative')
    checks=self_tests();print(f"{checks['passed']} startup checks passed.",flush=True)
    if args.self_test:return 0
    root=(args.output or Path('v35_verification' if args.verify else 'v35_smoke' if args.smoke else 'v35_results')).resolve()
    if root.suffix:ap.error('--output must be a directory without a suffix')
    root.mkdir(parents=True,exist_ok=True);awake=None
    if sys.platform=='darwin':
        try:awake=subprocess.Popen(['caffeinate','-dimsu','-w',str(os.getpid())])
        except FileNotFoundError:pass
    try:
        with RunLock(root):
            if args.verify:
                receipt=engineering_verification(True);write_json(root/'VERIFICATION.json',receipt);print('Full engineering verification passed.',flush=True);return 0
            runner=Runner(root,args.smoke,args.max_new_jobs);runner.setup()
            path=root/'VERIFICATION.json'
            if path.exists():
                envelope=json.loads(path.read_text());receipt=envelope['payload']
                if envelope.get('sha256')!=sha(receipt) or receipt.get('source_sha256')!=runner.identity['source_sha256'] or (not args.smoke and not receipt.get('full_length')):
                    raise RuntimeError('Corrupt or foreign verification receipt')
            else:
                receipt=engineering_verification(not args.smoke);write_json(path,{'payload':receipt,'sha256':sha(receipt)})
            write_json(root/'PREFLIGHT.json',checks)
            try:complete=runner.run()
            except KeyboardInterrupt:complete=False
            runner.finish(complete)
    finally:
        if awake is not None:awake.terminate()
    return 0


if __name__=='__main__':
    raise SystemExit(main())
